const quality = ['owner-format', 'owner-lint', 'repository-types', 'repository-build', 'owner-tests'];

test('approved batch maps all engineering activities without changing their other authority', () => {
  assert.equal(files.length, 24);
  const components = files.filter(({ path }) => path.includes('/components/'));
  assert.equal(components.length, 18);
  let mappings = 0;
  for (const file of components) {
    assert(file.before);
    const before = parse(file.before);
    const after = parse(file.content);
    for (const activity of ['testing', 'implementation']) {
      assert.equal(after.activities[activity].profile, before.activities[activity].profile, file.path);
      const old = before.activities[activity].operations as string[];
      const actual = after.activities[activity].operations as string[];
      assert.deepEqual(actual, [...old.filter((id) => !quality.includes(id)), ...quality], file.path);
      after.activities[activity].operations = old;
      mappings++;
    }
    assert.deepEqual(after, before, file.path);
  }
  assert.equal(mappings, 36);
});

test('approved quality operation definitions retain owner scope and read-only commands', () => {
  for (const [id, applicability, command] of [
    ['owner-format', 'owner-format-files', 'format:check'],
    ['owner-lint', 'owner-lint-files', 'lint'],
  ]) {
    const file = files.find(({ path }) => path.endsWith('/' + id + '.yaml'));
    assert(file);
    assert.equal(file.before, null);
    const operation = parse(file.content);
    assert.equal(operation.applicability, applicability);
    assert.equal(operation.tool, 'check');
    assert.deepEqual(operation.args, ['run', command, '--', { context: 'owner' }]);
    assert.equal(operation.network, false);
  }
});

/** Overlay only approved guide bytes onto a separate capture for read-only inspection. */
function proposalCapture(active: Capture): Capture {
  const components = { ...active.components };
  const operations = { ...active.operations };
  const roles = { ...active.roles };
  for (const file of files) {
    const value = parse(file.content);
    if (file.path.includes('/components/')) components[value.id] = value;
    if (file.path.includes('/operations/')) operations[value.id] = value;
    if (file.path.includes('/roles/')) roles[value.id] = value;
  }
  return { ...active, components, operations, roles };
}

test('approved engineering bindings agree between inspection and activation request', () => {
  const architecture = new Architecture();
  const active = architecture.capture(process.cwd());
  const proposal = proposalCapture(active);
  for (const file of files.filter(({ path }) => path.includes('/components/'))) {
    const component = parse(file.content).id as string;
    for (const activity of ['testing', 'implementation']) {
      const selection = { component, activity };
      const inspected = architecture.request(proposal, selection);
      const activated = architecture.request(proposal, selection, { goal: 'fixture', worktree: '/fixture' });
      assert.deepEqual(activated.request.options.tools, inspected.request.options.tools, `${component}/${activity}`);
      assert.deepEqual(inspected.request.options.tools.map(({ name }) => name), proposal.components[component]!.activities[activity]!.operations);
    }
  }
});

test('proposal inspection leaves captured authority and assembled checks unchanged', () => {
  const architecture = new Architecture();
  const active = architecture.capture(process.cwd());
  const before = JSON.stringify(active);
  const proposal = proposalCapture(active);
  architecture.request(proposal, { component: 'architecture', activity: 'testing' });
  assert.equal(JSON.stringify(active), before);
  assert.deepEqual(proposal.project.checks?.acceptance, [
    'repository-build', 'repository-types', 'repository-format', 'repository-lint', 'repository-tests',
  ]);
  assert.deepEqual(proposal.project, active.project);
  assert.deepEqual(proposal.contracts, active.contracts);
});

test('approved mappings preserve optional research bindings', () => {
  const architecture = new Architecture();
  const active = architecture.capture(process.cwd());
  const proposal = proposalCapture(active);
  for (const file of files.filter(({ path }) => path.includes('/components/'))) {
    const component = parse(file.content).id as string;
    assert.deepEqual(proposal.components[component]!.activities.research, active.components[component]!.activities.research);
    for (const activity of ['testing', 'implementation']) {
      const operations = proposal.components[component]!.activities[activity]!.operations;
      assert.equal(operations.includes('request-research'), active.components[component]!.activities[activity]!.operations.includes('request-research'));
    }
  }
});
